import pandas as pd


def _same_plan(a, b):
    a_is_na = pd.isna(a)
    b_is_na = pd.isna(b)
    if a_is_na and b_is_na:
        return True
    if a_is_na or b_is_na:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim_account = inputs["dim_account"]
    stg_account = inputs["stg_account"]

    # Build initial state: account_id -> list of version dicts (mutable)
    state = {}
    for _, row in dim_account.iterrows():
        acc = int(row["account_id"])
        versions = state.setdefault(acc, [])
        versions.append({
            "plan": row["plan"],
            "eff_start_date": row["eff_start_date"],
            "eff_end_date": row["eff_end_date"],
            "is_current": int(row["is_current"]),
        })

    # Sort staging by account_id, update_date ASC
    stg_sorted = stg_account.sort_values(
        by=["account_id", "update_date"], kind="mergesort"
    )

    for _, srow in stg_sorted.iterrows():
        s_acc = int(srow["account_id"])
        s_plan = srow["plan"]
        s_date = srow["update_date"]

        versions = state.setdefault(s_acc, [])

        if len(versions) == 0:
            versions.append({
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            })
            continue

        # find covering version
        covering = None
        for v in versions:
            start = v["eff_start_date"]
            end = v["eff_end_date"]
            if start <= s_date and (pd.isna(end) or s_date < end):
                covering = v
                break

        if covering is None:
            # earliest version
            f = min(versions, key=lambda v: v["eff_start_date"])
            versions.append({
                "plan": s_plan,
                "eff_start_date": s_date,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            v = covering
            if _same_plan(v["plan"], s_plan):
                pass
            elif s_date == v["eff_start_date"]:
                v["plan"] = s_plan
            else:
                versions.append({
                    "plan": s_plan,
                    "eff_start_date": s_date,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                })
                v["eff_end_date"] = s_date
                v["is_current"] = 0

    # Flatten output
    records = []
    for acc, versions in state.items():
        for v in versions:
            records.append({
                "account_id": acc,
                "plan": v["plan"],
                "eff_start_date": v["eff_start_date"],
                "eff_end_date": v["eff_end_date"],
                "is_current": v["is_current"],
            })

    out = pd.DataFrame(
        records,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if not out.empty:
        out = out.sort_values(
            by=["account_id", "eff_start_date"], kind="mergesort"
        ).reset_index(drop=True)
        out["account_id"] = out["account_id"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])
        out["is_current"] = out["is_current"].astype("int64")
    else:
        out = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "plan": pd.Series(dtype="object"),
                "eff_start_date": pd.Series(dtype="datetime64[us]"),
                "eff_end_date": pd.Series(dtype="datetime64[us]"),
                "is_current": pd.Series(dtype="int64"),
            }
        )

    return {"dim_account_out": out}
